(()=>{
 'use strict';
 const root=document.createElement('div');root.id='boss-root';document.body.appendChild(root);
 const icon=n=>`<i data-lucide="${n}" aria-hidden="true"></i>`;
 let emblemIndex=0;
 const emblem=()=>{const id=`boss-metal-${++emblemIndex}`;return `<svg class="boss-emblem" viewBox="0 0 80 80" fill="none" aria-hidden="true" focusable="false"><defs><linearGradient id="${id}" x1="12" y1="5" x2="64" y2="77" gradientUnits="userSpaceOnUse"><stop stop-color="#f3f4df"/><stop offset=".35" stop-color="#9fc6cc"/><stop offset=".55" stop-color="#f0f9f5"/><stop offset="1" stop-color="#5f8c9e"/></linearGradient></defs><path d="M40 4 70 21v38L40 76 10 59V21Z" fill="#0b202b" stroke="url(#${id})" stroke-width="1.5"/><path d="m40 10 24 14v32L40 70 16 56V24Z" stroke="#83b9c2" stroke-opacity=".25"/><path d="M28 22h14c10 0 15 5 15 12 0 4-2 7-5 9 4 2 6 5 6 9 0 8-6 13-16 13H28V22Zm8 8v10h6c5 0 7-2 7-5s-2-5-7-5h-6Zm0 18v9h7c5 0 7-1 7-4 0-4-3-5-7-5h-7Z" fill="url(#${id})" transform="translate(0 -3)"/><path d="m40 1 3 5-3 5-3-5Z" fill="#e9d5ad"/><path d="M5 33v14M75 33v14" stroke="#c2dfe0" stroke-width="1.5" stroke-linecap="round"/></svg>`;};
 root.innerHTML=`<div class="boss-dock"><button id="boss-wake" class="boss-wake" aria-label="Set up voice activation for Boss" title="Voice activation">${icon('mic')}</button><button id="boss-launch" class="boss-launch" aria-label="Ask Boss" aria-haspopup="dialog" aria-controls="boss-panel"><span class="boss-launch-mark">${emblem()}</span><span><strong>Ask Boss</strong><small id="boss-dock-status">Ask directly. Learn clearly.</small></span><span class="boss-dock-wave" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i><i></i><i></i><i></i><i></i></span>${icon('arrow-up-right')}</button></div><dialog id="boss-panel" class="boss-panel" aria-labelledby="boss-title"><div class="boss-chrome"><div><span class="boss-logo">${emblem()}</span><span><strong id="boss-title">BOSS<span>.</span></strong><small>YOUR PERSONAL STUDY INTELLIGENCE</small></span></div><div class="boss-header-actions"><button id="boss-new" aria-label="Start a new Boss conversation" title="New conversation">${icon('message-square-plus')}</button><button id="boss-close" aria-label="Close Boss">${icon('x')}</button></div></div><div class="boss-live-signal"><span class="boss-voice-bars" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></span><span id="boss-signal-label">READY WHEN YOU ARE</span><span>VOICE + CHAT</span></div><div id="boss-scroll" class="boss-scroll"><section class="boss-welcome" id="boss-welcome"><div class="boss-core" aria-hidden="true"><span></span><span></span><span></span>${emblem()}</div><div class="boss-eyebrow">THINK CLEARER. BUILD WITH CONFIDENCE.</div><h2>Your question.<br>A <em>clearer next step.</em></h2><p>Ask about this site, your project, or a concept. I’ll get straight to your question.</p><button class="boss-talk" id="boss-talk" type="button">${icon("audio-lines")}Talk to Boss</button><p class="boss-voice-caption">Voice questions are sent automatically after you finish speaking.</p><div class="boss-prompts"><button data-boss-prompt="Explain the concept I am learning with a simple example.">${icon('book-open')}Explain a concept</button><button data-boss-prompt="Help me understand what to build for my current project, step by step.">${icon('layers-3')}Help with my project</button><button data-boss-prompt="How can I compare career directions related to my course without rushing the decision?">${icon('compass')}Explore my direction</button><button id="boss-guide">${icon('map')}How this site works</button></div></section><div id="boss-thread" class="boss-thread" role="log" aria-label="Conversation with Boss" aria-live="polite" aria-relevant="additions"></div><details class="boss-voice-settings" id="boss-voice-settings"><summary>${icon('audio-lines')}Voice & “Hey Boss” controls</summary><p>Voice uses your browser’s speech service, which may send audio to its provider. Microphone access starts only when you enable it. Availability varies by browser.</p><button id="boss-enable-wake" class="boss-sub-button">${icon('mic')}Enable listening for “Boss”</button><button id="boss-dictation" class="boss-sub-button" type="button">Dictate text without sending</button><p class="boss-tiny">Say “Hey Boss” followed by your question to get a direct spoken answer. After each reply, conversation mode listens again. Close Boss, stop the mic, or leave this tab to end the voice session.</p></details><details id="boss-setup" class="boss-setup"><summary>AI connection setup for the site owner</summary><p>Set AI_PROVIDER and its API key in the server environment or private .env file (GROQ_API_KEY for Groq, OPENAI_API_KEY for OpenAI), then restart the local server. Do not paste keys into chat or browser code. Chat requests can incur provider charges.</p><button id="boss-refresh" class="boss-sub-button">Check connection again</button></details></div><div class="boss-compose-area"><div class="boss-status" id="boss-status" role="status">Checking AI connection…</div><form id="boss-form"><label class="boss-sr-only" for="boss-input">Ask Boss a question</label><textarea id="boss-input" rows="2" maxlength="4000" placeholder="What’s on your mind?" required></textarea><div class="boss-compose-tools"><div><button id="boss-dictate" type="button" aria-label="Talk to Boss">${icon('mic')}</button><button id="boss-speak" type="button" aria-label="Mute spoken replies" aria-pressed="true">${icon('volume-2')}</button><button id="boss-replay" type="button" aria-label="Play last answer aloud" disabled>${icon('circle-play')}</button><label class="boss-context"><input id="boss-context" type="checkbox" checked>Use learning context</label></div><button type="submit" id="boss-send" aria-label="Send question to Boss">${icon('arrow-up')}</button></div></form><p class="boss-privacy">When connected, messages and selected course/lesson context go to the configured AI provider. Chat stays in this tab. AI can make mistakes.</p></div><div class="boss-summon" aria-hidden="true">${emblem()}<span>BOSS</span><small>READY FOR YOUR QUESTION.</small></div></dialog>`;
 window.initBoss(root);
})();
